import type { Tape } from './replay';
import tape from './tape.json';

/**
 * The recording the preview replays. It is generated by `tools/record-tape.ts`
 * from a real sandbox run through the real client, so what a judge watches is
 * what PayPal actually answered, not a hand-written fixture.
 */
export function recordedTape(): Tape | null {
	const candidate = tape as Tape;
	return candidate.entries.length > 0 ? candidate : null;
}
